47	                                    String reason, String applicantActor) {
48	        if (reason == null || reason.isBlank()) {
49	            throw ApiException.badRequest("reason 不能为空");
50	        }
51	        if (reason.length() > 500) {
52	            throw ApiException.badRequest("reason 最长 500 字符");
53	        }
54	        AllocationRow allocation =
55	                experimentService.mustFindAllocationRow(experimentId, participantId);
56	        UnblindRequestRow pending =
57	                unblindRequestRepository.findPendingByAllocation(allocation.id());
58	        if (pending != null) {
59	            throw ApiException.conflict("该分配已存在待审揭盲申请");
60	        }
61	        String requestId = "UB-" + UUID.randomUUID().toString().replace("-", "");
62	        long now = clock.nowMillis();
63	        UnblindRequestRow row = new UnblindRequestRow(requestId, experimentId, participantId,
64	                allocation.id(), reason, applicantActor, null, "PENDING", null, now, null);
65	        try {
66	            unblindRequestRepository.insertPending(row);
67	        } catch (DuplicateKeyException e) {
68	            // 并发申请同一分配：唯一待审占位兜底。
69	            throw ApiException.conflict("该分配已存在待审揭盲申请");
