160	    @Test
161	    void apply_requiresReason_andOnlyOnePendingPerAllocation() {
162	        setupExperimentWithParticipant("UB-2", "u2");
163	
164	        // REVIEWER 不能申请揭盲
165	        assertEquals(403, exchange(
166	                "/api/experiments/UB-2/participants/PA/unblind-requests", HttpMethod.POST,
167	                headers("rev-2", "REVIEWER", "u2-apply-by-reviewer"),
168	                "{\"reason\":\"x\"}").getStatusCode().value());
169	
170	        // 原因缺失
171	        assertEquals(400, exchange(
172	                "/api/experiments/UB-2/participants/PA/unblind-requests", HttpMethod.POST,
173	                headers("coord-1", "COORDINATOR", "u2-apply-blank"),
174	                "{\"reason\":\"\"}").getStatusCode().value());
175	
176	        // 正常申请
177	        ResponseEntity<String> first = exchange(
178	                "/api/experiments/UB-2/participants/PA/unblind-requests", HttpMethod.POST,
179	                headers("coord-1", "COORDINATOR", "u2-apply-1"),
180	                "{\"reason\":\"首次申请\"}");
181	        assertEquals(201, first.getStatusCode().value());
182	
183	        // 同一分配第二个待审申请 409
184	        ResponseEntity<String> second = exchange(
185	                "/api/experiments/UB-2/participants/PA/unblind-requests", HttpMethod.POST,
186	                headers("coord-1", "COORDINATOR", "u2-apply-2"),
187	                "{\"reason\":\"再次申请\"}");
188	        assertEquals(409, second.getStatusCode().value());
189	
190	        // 为不存在的参与者申请：404
191	        assertEquals(404, exchange(
192	                "/api/experiments/UB-2/participants/NOBODY/unblind-requests", HttpMethod.POST,
193	                headers("coord-1", "COORDINATOR", "u2-apply-missing"),
194	                "{\"reason\":\"x\"}").getStatusCode().value());
195	    }
196	
