package com.example.starter.blind;

import org.springframework.boot.test.context.TestConfiguration;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Primary;
import org.springframework.jdbc.core.JdbcTemplate;

/**
 * 测试时钟配置：以可控时钟替换系统墙钟；
 * MutableTestClock 实现 Clock，Clock 类型注入点按 @Primary 命中该 Bean。
 * 同时注册 H2 释放 Bean，上下文结束时关闭命名内存库。
 */
@TestConfiguration
public class TestClockConfig {

    @Bean
    @Primary
    public MutableTestClock mutableTestClock() {
        return new MutableTestClock();
    }

    @Bean
    public H2ShutdownBean h2ShutdownBean(JdbcTemplate jdbc) {
        return new H2ShutdownBean(jdbc);
    }
}

package com.example.starter.blind;

/**
 * 操作者角色，本题信任本地测试头 X-Role。
 */
public enum Role {
    /** 协调员：实验管理、登记、退组、揭盲申请。 */
    COORDINATOR,
    /** 审阅员：仅可普通查询、批准揭盲申请。 */
    REVIEWER
}

package com.example.starter.blind.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * 揭盲申请请求体。
 *
 * @param reason 揭盲原因，必填
 */
public record UnblindApplyRequest(
        @NotBlank(message = "reason 不能为空")
        @Size(max = 500, message = "reason 最长 500 字符")
        String reason
) {
}

package com.example.starter.blind;

/**
 * 实验状态。
 */
public enum ExperimentStatus {
    /** 开放登记。 */
    OPEN,
    /** 已关闭，拒绝新增分配。 */
    CLOSED
}

